try:
    result = pd.date_range('2020-01-01', periods=5).get_indexer(DatetimeIndex([pd.NaT], dtype='datetime64[ns]'), method='nearest')
    probe("pd.date_range('2020-01-01', periods=5).get_indexer(DatetimeIndex([pd.NaT], dtype=...), method='nearest')", result)
